package io.github.jesterportfolio.hearth.combat;

import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.quest.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

/** 격리 공개 의뢰의 입장/승리 연결. 개인 퀘스트 저장·전투·세션 체계를 재사용합니다. */
public final class DungeonPlay implements AutoCloseable {
    public record Definition(String id,String quest,String npc,QuestContent.Area entry){
        public Definition{for(var k:List.of(id,quest,npc))if(!k.matches("[a-z][a-z0-9_]{0,63}"))throw new IllegalArgumentException("DUNGEON_ID");Objects.requireNonNull(entry);}
        public String reference(){return "dungeon:"+id;}
        public void validate(QuestContent q,CombatContent combat){if(!combat.id().equals(id)||!q.id().equals(quest)||!q.npcId().equals(npc)||q.goals().stream().filter(g->reference().equals(g.interaction())).count()!=1||combat.path()==null||combat.path().checkpoints().stream().anyMatch(cp->!cp.quest().equals(quest)))throw new IllegalArgumentException("DUNGEON_LINK");}
        public static Definition parse(Map<?,?> root){if(!Integer.valueOf(1).equals(root.get("format"))||!Boolean.TRUE.equals(root.get("isolated-current-session-credit")))throw new IllegalArgumentException("DUNGEON_FORMAT");var a=(Map<?,?>)root.get("entry-area");var bounds=new QuestContent.Area(n(a,"min-x"),n(a,"max-x"),n(a,"min-y"),n(a,"max-y"),n(a,"min-z"),n(a,"max-z"));if(bounds.minX()>bounds.maxX()||bounds.minY()>bounds.maxY()||bounds.minZ()>bounds.maxZ())throw new IllegalArgumentException("DUNGEON_AREA");return new Definition((String)root.get("id"),(String)root.get("quest"),(String)root.get("npc"),bounds);}
        private static double n(Map<?,?> m,String k){if(!(m.get(k) instanceof Number n)||!Double.isFinite(n.doubleValue()))throw new IllegalArgumentException("DUNGEON_AREA");return n.doubleValue();}
    }
    public interface Actor {ServerProgressAccess.Context context();Object token();UUID world();long generation();boolean current();boolean atEntry();void freeze(boolean value);}
    public interface Boundary {List<Actor> nearby(UUID run);boolean available(UUID run);boolean allowed(Actor actor);CompletionStage<Void> save(UUID run);CombatAttempt start(List<Actor> selected);}
    public enum Phase{CHECKING,SAVING,STARTING,ACTIVE,CREDITING,REPORT_READY,HOLD}
    private static final class Entry {final UUID run,world;final long generation;final Actor requester;final Map<UUID,Object> nearby;final CompletableFuture<CombatAttempt> result=new CompletableFuture<>();final List<Actor> frozen=new ArrayList<>();final Map<Actor,PersonalQuest.Session> selected=new LinkedHashMap<>();volatile Phase phase=Phase.CHECKING;CombatAttempt battle;boolean path=true;CompletionStage<Void> victory;int offline;Entry(Actor actor,Map<UUID,Object> nearby){run=actor.context().storyRunId();world=actor.world();generation=actor.generation();requester=actor;this.nearby=nearby;}}
    private final Definition definition;private final QuestContent content;private final PersonalQuest quests;private final Boundary boundary;private final Executor owner;private final Runnable check;private final Map<UUID,Entry> entries=new HashMap<>();private boolean closed;
    public DungeonPlay(Definition definition,QuestContent content,PersonalQuest quests,Boundary boundary,Executor owner,Runnable check){this.definition=definition;this.content=content;this.quests=quests;this.boundary=boundary;this.owner=owner;this.check=check;}
    private static Map<UUID,Object> roster(List<Actor> actors){var m=new HashMap<UUID,Object>();for(var a:actors)if(m.put(a.context().playerId(),a.token())!=null||a.token()==null)throw new IllegalStateException("DUNGEON_DUPLICATE_ACTOR");return Map.copyOf(m);}
    private boolean actor(Actor a,Entry e){return a.current()&&a.context().storyRunId().equals(e.run)&&a.world().equals(e.world)&&a.generation()==e.generation;}
    private void require(Entry e,BooleanSupplier dialogue){check.run();if(closed||e.result.isDone()||e.phase==Phase.HOLD||entries.get(e.run)!=e||!actor(e.requester,e)||!dialogue.getAsBoolean()||!boundary.available(e.run)||!roster(boundary.nearby(e.run)).equals(e.nearby))throw new IllegalStateException("DUNGEON_STALE");}
    private boolean goal(PersonalQuest.Session s){return !s.busy()&&!s.held()&&s.saved().phase()==QuestStore.Phase.ACTIVE&&definition.reference().equals(content.goal(s.saved()).interaction());}
    public CompletionStage<CombatAttempt> enter(Actor requester,String npc,BooleanSupplier dialogue){check.run();if(closed||!definition.npc().equals(npc)||!requester.current()||!requester.atEntry()||!dialogue.getAsBoolean())return CompletableFuture.failedFuture(new IllegalStateException("DUNGEON_ENTRY"));UUID run=requester.context().storyRunId();var old=entries.get(run);if(old!=null)return !old.result.isDone()&&old.requester.token()==requester.token()?old.result:CompletableFuture.failedFuture(new IllegalStateException("DUNGEON_BUSY_OR_HOLD"));
        var candidates=List.copyOf(boundary.nearby(run));if(candidates.isEmpty()||candidates.size()>32||!boundary.available(run))return CompletableFuture.failedFuture(new IllegalStateException("DUNGEON_NOT_READY"));if(candidates.stream().anyMatch(a->!a.context().storyRunId().equals(run)))return CompletableFuture.failedFuture(new IllegalStateException("DUNGEON_OWNER"));Map<UUID,Object> captured;try{captured=roster(candidates);}catch(RuntimeException invalid){return CompletableFuture.failedFuture(invalid);}var e=new Entry(requester,captured);entries.put(run,e);
        CompletionStage<Void> work=CompletableFuture.completedFuture(null);for(var a:candidates)work=work.thenComposeAsync(v->{require(e,dialogue);if(!actor(a,e)||!a.atEntry())throw new IllegalStateException("DUNGEON_ACTOR");return quests.open(a.context(),definition.quest(),a.token(),a::current).thenAcceptAsync(q->{require(e,dialogue);if(q.held()||q.busy())throw new IllegalStateException("DUNGEON_QUEST_HOLD");if(goal(q)&&boundary.allowed(a))e.selected.put(a,q);},owner);},owner);
        work.thenComposeAsync(v->{require(e,dialogue);if(e.selected.keySet().stream().noneMatch(a->a.context().playerId().equals(requester.context().playerId())&&a.token()==requester.token()))throw new IllegalStateException("DUNGEON_QUEST_REQUIRED");e.phase=Phase.SAVING;for(var a:e.selected.keySet()){a.freeze(true);e.frozen.add(a);}return boundary.save(run);},owner)
            .thenApplyAsync(v->{require(e,dialogue);if(e.selected.entrySet().stream().anyMatch(x->!actor(x.getKey(),e)||!x.getKey().atEntry()||!goal(x.getValue())||!boundary.allowed(x.getKey())))throw new IllegalStateException("DUNGEON_GOAL_CHANGED");e.phase=Phase.STARTING;var battle=Objects.requireNonNull(boundary.start(List.copyOf(e.selected.keySet())));var s=battle.snapshot();if(!s.run().equals(run)||s.generation()!=e.generation||!battle.worldId().equals(e.world)||s.phase()!=CombatAttempt.Phase.ACTIVE||!battle.onlineSessions().equals(roster(List.copyOf(e.selected.keySet())))){battle.invalidate();throw new IllegalStateException("DUNGEON_BAD_START");}e.battle=battle;e.phase=Phase.ACTIVE;return battle;},owner)
            .toCompletableFuture().orTimeout(30,TimeUnit.SECONDS).whenCompleteAsync((battle,error)->{Throwable failure=error;for(var a:e.frozen)try{a.freeze(false);}catch(RuntimeException ex){if(failure==null)failure=ex;}e.frozen.clear();if(failure==null)e.result.complete(battle);else{if(e.phase==Phase.CHECKING){entries.remove(run,e);}else e.phase=Phase.HOLD;e.result.completeExceptionally(failure);}},owner).exceptionally(error->{e.phase=Phase.HOLD;e.result.completeExceptionally(error);return null;});return e.result;
    }
    public void changed(CombatAttempt previous,CombatAttempt next,boolean path){check.run();var e=entries.get(previous.snapshot().run());if(e==null)return;var before=previous.snapshot();var after=next.snapshot();var ids=e.selected.keySet().stream().map(a->a.context().playerId()).collect(java.util.stream.Collectors.toSet());if(closed||e.phase==Phase.HOLD||e.battle!=previous||before.phase()!=CombatAttempt.Phase.CLOSED||before.error()!=null||!Set.of(CombatAttempt.Outcome.RETIRED,CombatAttempt.Outcome.RETRY,CombatAttempt.Outcome.REQUIRED_FAILURE).contains(before.outcome())||!after.run().equals(e.run)||after.generation()!=e.generation||!next.worldId().equals(e.world)||after.phase()!=CombatAttempt.Phase.ACTIVE||after.members().stream().anyMatch(m->!ids.contains(m.player())))throw new IllegalStateException("DUNGEON_BATTLE_CHAIN");e.battle=next;e.path=path;e.victory=null;}
    public CompletionStage<Void> victory(CombatAttempt battle,List<Actor> online){check.run();var e=entries.get(battle.snapshot().run());if(e==null)return CompletableFuture.completedFuture(null);if(e.victory!=null)return e.victory;var s=battle.snapshot();if(closed||e.battle!=battle||e.path||s.phase()!=CombatAttempt.Phase.CLOSED||s.outcome()!=CombatAttempt.Outcome.VICTORY||s.error()!=null)return CompletableFuture.failedFuture(new IllegalStateException("DUNGEON_NOT_VICTORIOUS"));var selected=List.copyOf(online);if(!battle.onlineSessions().equals(roster(selected))||selected.stream().anyMatch(a->!actor(a,e)))return CompletableFuture.failedFuture(new IllegalStateException("DUNGEON_VICTORY_SESSION"));e.phase=Phase.CREDITING;e.offline=(int)s.members().stream().filter(m->!m.online()).count();
        CompletionStage<Void> work=CompletableFuture.completedFuture(null);for(var a:selected)work=work.thenComposeAsync(v->{if(closed||!actor(a,e))throw new IllegalStateException("DUNGEON_STALE_CREDIT");return quests.open(a.context(),definition.quest(),a.token(),a::current).thenComposeAsync(q->{if(closed||!actor(a,e)||q.busy()||q.held())throw new IllegalStateException("DUNGEON_CREDIT_HOLD");if(q.saved().phase()==QuestStore.Phase.REPORT_READY||q.saved().phase()==QuestStore.Phase.COMPLETED)return CompletableFuture.completedFuture(null);if(!goal(q))throw new IllegalStateException("DUNGEON_CREDIT_GOAL");return quests.interact(q,content,definition.reference()).thenApply(x->(Void)null);},owner);},owner);
        e.victory=work.toCompletableFuture().orTimeout(30,TimeUnit.SECONDS).thenRunAsync(()->{if(closed||selected.stream().anyMatch(a->!actor(a,e)))throw new IllegalStateException("DUNGEON_STALE_CREDIT");},owner).whenCompleteAsync((v,error)->e.phase=error==null?Phase.REPORT_READY:Phase.HOLD,owner);e.victory.exceptionally(error->{e.phase=Phase.HOLD;return null;});return e.victory;
    }
    public boolean registered(CombatAttempt battle){check.run();var e=entries.get(battle.snapshot().run());return e!=null&&e.battle==battle;}
    public List<String> lines(Actor actor){check.run();var e=entries.get(actor.context().storyRunId());if(e==null)return List.of("담당 NPC 가까이에서 활성 던전 의뢰로 입장을 요청하세요.");if(!actor(actor,e)||e.selected.keySet().stream().noneMatch(a->a.context().playerId().equals(actor.context().playerId())))return List.of("현재 참가 중인 공개 던전이 없습니다.");return List.of("공개 던전 진행: "+switch(e.phase){case CHECKING->"참가 조건 확인 중";case SAVING->"입장 전 저장 중";case STARTING->"전투 준비 중";case ACTIVE->e.path?"길목 진행 중":"보스 도전 중";case CREDITING->"승리 목표 저장 중";case REPORT_READY->"온라인 대상 목표 저장 완료 · 개인 보고/완료 기록을 확인하세요";case HOLD->"처리 보류 · 성공으로 간주하지 않습니다.";},"세부 전투 안내: /hearthcombat status",e.offline>0?"오프라인 참가자의 개인 목표 반영은 이번 개발 모드에서 보류합니다.":"개인 목표와 완료 보고는 본인 기록으로 처리합니다.");}
    public CompletionStage<Void> barrier(UUID run){check.run();var e=entries.get(run);return e==null?CompletableFuture.completedFuture(null):e.result.thenComposeAsync(v->e.victory==null?CompletableFuture.completedFuture(null):e.victory,owner);}
    public void unloaded(UUID run){check.run();var e=entries.get(run);if(e==null)return;if(e.phase==Phase.HOLD||!e.result.isDone()||e.result.isCompletedExceptionally()||e.victory!=null&&(!e.victory.toCompletableFuture().isDone()||e.victory.toCompletableFuture().isCompletedExceptionally())||e.battle!=null&&e.battle.snapshot().phase()!=CombatAttempt.Phase.CLOSED)throw new IllegalStateException("DUNGEON_UNLOAD_PENDING_OR_HOLD");entries.remove(run,e);}
    public void close(){check.run();closed=true;for(var e:entries.values())if(!e.result.isDone()){e.phase=Phase.HOLD;e.result.completeExceptionally(new IllegalStateException("DUNGEON_CLOSED"));}}
}
